        if (line.indexOf('塔') !== -1 && line.indexOf('读') !== -1 && line.indexOf('说') !== -1) {
            continue; 
        }
        cleanArr.push(line);
    }
    // 把干净的行重新拼装起来
    res = cleanArr.join('');
} catch(e) {}
